import { createReadStream, existsSync, statSync } from "node:fs";
import { createServer } from "node:http";
import type { IncomingMessage, ServerResponse } from "node:http";
import { extname, resolve } from "node:path";
import { Readable } from "node:stream";

// @ts-ignore - dist/server/server.js is generated by TanStack Start build
import server from "./dist/server/server.js";

interface ServerHandler {
  fetch: (req: Request) => Promise<Response>;
}

const PORT: number = Number(process.env.PORT) || 3000;
const CLIENT_DIR: string = resolve(process.cwd(), "dist", "client");

const ssrHandler: (req: Request) => Promise<Response> =
  (server as { default?: ServerHandler }).default?.fetch ?? server.fetch;

const MIME_TYPES: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".webp": "image/webp",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
  ".ttf": "font/ttf",
  ".wasm": "application/wasm",
};

const toWebRequest = (req: IncomingMessage): Request => {
  const host: string = req.headers.host ?? "localhost:3000";
  const protocol: string =
    req.headers["x-forwarded-proto"]?.toString() ?? "http";
  const url: URL = new URL(req.url ?? "/", `${protocol}://${host}`);

  const headers: Headers = new Headers();
  for (const [key, val] of Object.entries(req.headers)) {
    if (val !== undefined) {
      if (Array.isArray(val)) {
        for (const item of val) {
          headers.append(key, item);
        }
      } else {
        headers.set(key, val);
      }
    }
  }

  const hasBody: boolean = req.method !== "GET" && req.method !== "HEAD";
  const body: ReadableStream<Uint8Array> | undefined = hasBody
    ? (Readable.toWeb(req) as ReadableStream<Uint8Array>)
    : undefined;

  return new Request(url, {
    method: req.method,
    headers,
    body,
    // @ts-ignore - duplex is standard in Node fetch/web Request with stream body
    duplex: "half",
  });
};

const nodeServer = createServer(
  async (req: IncomingMessage, res: ServerResponse): Promise<void> => {
    const rawUrl: string = req.url ?? "/";
    const pathname: string = rawUrl.split("?")[0];

    // Attempt to serve static asset from dist/client
    if (pathname !== "/") {
      const relativePath: string = pathname.replace(/^\//, "");
      const filePath: string = resolve(CLIENT_DIR, relativePath);

      if (existsSync(filePath) && statSync(filePath).isFile()) {
        const ext: string = extname(filePath).toLowerCase();
        const contentType: string =
          MIME_TYPES[ext] ?? "application/octet-stream";
        const isImmutableAsset: boolean = pathname.startsWith("/assets/");

        res.writeHead(200, {
          "Content-Type": contentType,
          "Cache-Control": isImmutableAsset
            ? "public, max-age=31536000, immutable"
            : "public, max-age=3600",
        });

        createReadStream(filePath).pipe(res);
        return;
      }
    }

    // Dynamic SSR request handling
    try {
      const webRequest: Request = toWebRequest(req);
      const webResponse: Response = await ssrHandler(webRequest);

      const responseHeaders: Record<string, string | string[]> = {};
      webResponse.headers.forEach((value: string, key: string) => {
        if (key.toLowerCase() === "set-cookie") {
          const existing = responseHeaders[key];
          if (Array.isArray(existing)) {
            existing.push(value);
          } else if (existing) {
            responseHeaders[key] = [existing, value];
          } else {
            responseHeaders[key] = value;
          }
        } else {
          responseHeaders[key] = value;
        }
      });

      res.writeHead(
        webResponse.status,
        webResponse.statusText,
        responseHeaders,
      );

      if (webResponse.body) {
        Readable.fromWeb(
          webResponse.body as unknown as import("node:stream/web").ReadableStream,
        ).pipe(res);
      } else {
        res.end();
      }
    } catch (error) {
      console.error("SSR Request Error:", error);
      if (!res.headersSent) {
        res.writeHead(500, { "Content-Type": "text/plain; charset=utf-8" });
      }
      res.end("Internal Server Error");
    }
  },
);

nodeServer.listen(PORT, (): void => {
  console.log(
    `🚀 Production Node.js server running at http://localhost:${PORT}`,
  );
});
